        }
        if lhs.q != rhs.q {
            return false
        }
        if lhs.gain != rhs.gain {
            return false
        }
        if lhs.qp != rhs.qp {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(filterType)
        hasher.combine(bypass)
