/**
 * The result of [`firmware_guard_check`]. The default blocks.
 */
public struct FirmwareGuardVerdict {
    /**
     * True only for `Clear` and `Confirmed`. Anything else must not flash.
     */
    public var allowed: Bool
    /**
     * The decision.
     */
    public var decision: FirmwareGuardDecision
    /**
     * Why.
     */
    public var reason: FirmwareGuardReason
    /**
     * For the user, in English.
     */
    public var message: String
    /**
     * What to ask the user to type when a risk is involved, else "": the
     * phrase, or for [`FirmwareGuardReason::Overvolt`] the word. Compared
     * exactly: case and spaces count, and the one does not stand for the other.
     */
    public var confirmationPhrase: String
    /**
     * The image's stamped voltage in mV; 0 if it has none (taken as 1150).
     */
    public var imageMv: UInt16
    /**
     * The board record's `required_mv`, as given.
     */
    public var requiredMv: UInt16

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * True only for `Clear` and `Confirmed`. Anything else must not flash.
         */allowed: Bool, 
        /**
         * The decision.
         */decision: FirmwareGuardDecision, 
        /**
         * Why.
         */reason: FirmwareGuardReason, 
        /**
         * For the user, in English.
         */message: String, 
        /**
         * What to ask the user to type when a risk is involved, else "": the
         * phrase, or for [`FirmwareGuardReason::Overvolt`] the word. Compared
         * exactly: case and spaces count, and the one does not stand for the other.
         */confirmationPhrase: String, 
        /**
         * The image's stamped voltage in mV; 0 if it has none (taken as 1150).
         */imageMv: UInt16, 
        /**
         * The board record's `required_mv`, as given.
         */requiredMv: UInt16) {
        self.allowed = allowed
        self.decision = decision
        self.reason = reason
        self.message = message
        self.confirmationPhrase = confirmationPhrase
        self.imageMv = imageMv
        self.requiredMv = requiredMv
    }
}

