private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 29
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_dspi_core_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_dspi_core_checksum_func_about_json() != 52111) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_autoeq_database_info() != 16465) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_autoeq_import() != 53250) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_autoeq_rebuild_start() != 1987) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_autoeq_rebuild_warning() != 44310) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_autoeq_reset_to_builtin() != 62859) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_autoeq_update() != 14321) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_bootloader_counts() != 31649) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_bootloader_drives() != 58490) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_compute_magnitude_curve() != 49830) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_compute_phase_curve() != 11263) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dspi_core_checksum_func_compute_response() != 46454) {
        return InitializationResult.apiChecksumMismatch
